-- Forward-only M3-07 provenance contract repair.  Keep conflict values wire
-- compatible and make the worker projection field-decision-aware.

-- M3-05 already exposed this source family; these two physical rows were
-- omitted from its registry and would otherwise make export fail closed.
insert into public.organization_export_source_tables(source_id,table_name,tenant_key_column,record_order_column,table_sort)
values
  ('sbom_normalized_graph', 'sbom_diff_reports', 'organization_id', 'id', 9),
  ('sbom_normalized_graph', 'sbom_diff_component_changes', 'organization_id', 'id', 10)
on conflict(source_id,table_name) do update set tenant_key_column=excluded.tenant_key_column,record_order_column=excluded.record_order_column,table_sort=excluded.table_sort;

create or replace function public.normalize_sbom_composite_conflict_candidates()
returns trigger language plpgsql set search_path=public,pg_temp as $$
begin
  if new.conflict_type='field_conflict' and new.field_name='hashes' then
    new.candidates := (
      select jsonb_agg(
        jsonb_set(candidate.value,'{value}',to_jsonb(case when jsonb_typeof(candidate.value->'value') in ('array','object') then (candidate.value->'value')::text else candidate.value->>'value' end),true)
        order by candidate.ordinality
      )
      from jsonb_array_elements(new.candidates) with ordinality candidate(value,ordinality)
    );
  end if;
  return new;
end;
$$;

drop trigger if exists normalize_sbom_composite_conflict_candidates on public.sbom_composite_conflicts;
create trigger normalize_sbom_composite_conflict_candidates
before insert or update of candidates on public.sbom_composite_conflicts
for each row execute function public.normalize_sbom_composite_conflict_candidates();

-- Claims are restart-safe: projection rows are added once and use the review's
-- stable generated timestamp rather than a fresh worker timestamp.  No claim
-- deletes a prior field/dependency mapping.
create or replace function public.sync_sbom_composite_selected_provenance(p_organization_id uuid,p_review_id uuid)
returns void language plpgsql security definer set search_path=public,pg_temp as $$
begin
  with candidates as (
    select i.source_id,i.document_id,i.supplier_submission_id,c.id component_id,c.document_local_ref,c.source_offset,c.normalized_version,c.canonical_purl,c.cpe,c.hashes,public.sbom_composite_identity_key(c.canonical_purl,c.cpe,c.hashes,i.document_id,c.document_local_ref) identity_key,row_number() over(partition by public.sbom_composite_identity_key(c.canonical_purl,c.cpe,c.hashes,i.document_id,c.document_local_ref) order by i.source_id,c.source_offset,c.id) rn from public.sbom_composite_review_inputs i join public.sbom_components c on c.organization_id=i.organization_id and c.document_id=i.document_id where i.organization_id=p_organization_id and i.review_id=p_review_id
  ), decisions as (
    select c.identity_key,(array_agg(c.selected_source_component_id order by c.selected_source_component_id) filter(where c.conflict_type='incompatible_version' and c.selected_source_component_id is not null))[1] vc,(array_agg(c.selected_source_component_id order by c.selected_source_component_id) filter(where c.conflict_type='field_conflict' and c.selected_source_component_id is not null))[1] fc,bool_or(c.selected_source_component_id is null and c.resolution_reason is not null) excluded,bool_or(c.selected_source_component_id is null and c.resolution_reason is null) unresolved,count(*) conflict_count from public.sbom_composite_conflicts c where c.organization_id=p_organization_id and c.review_id=p_review_id group by c.identity_key
  ), selected as (
    select c.*,case when c.identity_key like 'unresolved:%' then 'component:'||c.document_id::text||':'||c.document_local_ref else 'component:'||encode(extensions.digest(c.identity_key||'@'||coalesce(c.normalized_version,''),'sha256'),'hex') end composite_ref from candidates c left join decisions d on d.identity_key=c.identity_key where not coalesce(d.excluded,false) and not coalesce(d.unresolved,false) and ((d.vc is not null and c.component_id=d.vc) or (d.vc is null and d.fc is not null and c.component_id=d.fc) or (d.conflict_count is null and c.rn=1) or c.identity_key like 'unresolved:%')
  )
  insert into public.sbom_composite_component_provenance(organization_id,review_id,composite_component_ref,field_name,source_id,source_document_id,source_component_id,source_component_ref,supplier_submission_id,merge_timestamp,review_conflict_id)
  select p_organization_id,p_review_id,s.composite_ref,f.field_name,chosen.source_id,chosen.document_id,chosen.component_id,chosen.document_local_ref,chosen.supplier_submission_id,coalesce((select r.generated_at from public.sbom_composite_reviews r where r.organization_id=p_organization_id and r.id=p_review_id),now()),(select c.id from public.sbom_composite_conflicts c where c.organization_id=p_organization_id and c.review_id=p_review_id and c.identity_key=s.identity_key and (c.conflict_type='incompatible_version' or c.field_name=f.field_name) and c.selected_source_component_id=chosen.component_id order by c.id limit 1)
  from selected s cross join lateral (values ('name'),('version'),('canonicalPurl'),('canonicalCpe'),('hashes')) f(field_name)
  cross join lateral (select coalesce((select c.selected_source_component_id from public.sbom_composite_conflicts c where c.organization_id=p_organization_id and c.review_id=p_review_id and c.identity_key=s.identity_key and c.conflict_type='field_conflict' and c.field_name=f.field_name and c.selected_source_component_id is not null order by c.id limit 1),s.component_id) component_id) choice
  join candidates chosen on chosen.component_id=choice.component_id
  on conflict (organization_id,review_id,composite_component_ref,field_name,source_component_id) do nothing;

  with candidates as (
    select i.source_id,i.document_id,i.supplier_submission_id,c.id component_id,c.document_local_ref,c.source_offset,c.normalized_version,c.canonical_purl,c.cpe,c.hashes,public.sbom_composite_identity_key(c.canonical_purl,c.cpe,c.hashes,i.document_id,c.document_local_ref) identity_key,row_number() over(partition by public.sbom_composite_identity_key(c.canonical_purl,c.cpe,c.hashes,i.document_id,c.document_local_ref) order by i.source_id,c.source_offset,c.id) rn from public.sbom_composite_review_inputs i join public.sbom_components c on c.organization_id=i.organization_id and c.document_id=i.document_id where i.organization_id=p_organization_id and i.review_id=p_review_id
  ), decisions as (
    select c.identity_key,(array_agg(c.selected_source_component_id order by c.selected_source_component_id) filter(where c.conflict_type='incompatible_version' and c.selected_source_component_id is not null))[1] vc,(array_agg(c.selected_source_component_id order by c.selected_source_component_id) filter(where c.conflict_type='field_conflict' and c.selected_source_component_id is not null))[1] fc,bool_or(c.selected_source_component_id is null and c.resolution_reason is not null) excluded,bool_or(c.selected_source_component_id is null and c.resolution_reason is null) unresolved,count(*) conflict_count from public.sbom_composite_conflicts c where c.organization_id=p_organization_id and c.review_id=p_review_id group by c.identity_key
  ), selected as (
    select c.component_id,case when c.identity_key like 'unresolved:%' then 'component:'||c.document_id::text||':'||c.document_local_ref else 'component:'||encode(extensions.digest(c.identity_key||'@'||coalesce(c.normalized_version,''),'sha256'),'hex') end component_ref from candidates c left join decisions d on d.identity_key=c.identity_key where not coalesce(d.excluded,false) and not coalesce(d.unresolved,false) and ((d.vc is not null and c.component_id=d.vc) or (d.vc is null and d.fc is not null and c.component_id=d.fc) or (d.conflict_count is null and c.rn=1) or c.identity_key like 'unresolved:%')
  )
  insert into public.sbom_composite_dependency_provenance(organization_id,review_id,composite_parent_ref,composite_child_ref,source_dependency_id,source_id,source_document_id,supplier_submission_id,merge_timestamp)
  select p_organization_id,p_review_id,parent.component_ref,child.component_ref,d.id,i.source_id,i.document_id,i.supplier_submission_id,coalesce((select r.generated_at from public.sbom_composite_reviews r where r.organization_id=p_organization_id and r.id=p_review_id),now())
  from public.sbom_component_dependencies d join selected parent on parent.component_id=d.parent_component_id join selected child on child.component_id=d.child_component_id join public.sbom_composite_review_inputs i on i.organization_id=d.organization_id and i.review_id=p_review_id and i.document_id=d.document_id
  where d.organization_id=p_organization_id and d.edge_state='retained' and parent.component_ref<>child.component_ref
  on conflict (organization_id,review_id,source_dependency_id) do nothing;
end;
$$;

-- The emitted component may be a field-level composite.  A selected source
-- supplies each disputed field independently; version selection still wins for
-- the identity and all values remain present in source provenance above.
create or replace function public.claim_sbom_composite_generation(p_organization_id uuid,p_worker_id uuid,p_lease_seconds integer)
returns table(outcome text,work jsonb) language plpgsql security definer set search_path=public,pg_temp as $$
declare v_review public.sbom_composite_reviews%rowtype; v_components jsonb; v_dependencies jsonb;
begin
  if p_worker_id is null or p_lease_seconds not between 15 and 900 then return query select 'invalid_request'::text,null::jsonb; return; end if;
  select * into v_review from public.sbom_composite_reviews r where r.organization_id=p_organization_id and r.status='processing' and (r.lease_expires_at is null or r.lease_expires_at<=now()) and (r.generated_source_id is not null or r.attempt_count<5) order by r.created_at,r.id for update skip locked limit 1;
  if not found then return query select 'empty'::text,null::jsonb; return; end if;
  update public.sbom_composite_reviews r set lease_owner=p_worker_id,lease_expires_at=now()+make_interval(secs=>p_lease_seconds),attempt_count=r.attempt_count+case when r.generated_source_id is null then 1 else 0 end where r.organization_id=p_organization_id and r.id=v_review.id returning * into v_review;
  perform public.sync_sbom_composite_selected_provenance(p_organization_id,v_review.id);
  with candidates as (
    select i.source_id,i.document_id,c.id component_id,c.document_local_ref,c.source_offset,c.normalized_name,c.normalized_version,c.canonical_purl,c.cpe,c.hashes,public.sbom_composite_identity_key(c.canonical_purl,c.cpe,c.hashes,i.document_id,c.document_local_ref) identity_key,row_number() over(partition by public.sbom_composite_identity_key(c.canonical_purl,c.cpe,c.hashes,i.document_id,c.document_local_ref) order by i.source_id,c.source_offset,c.id) rn from public.sbom_composite_review_inputs i join public.sbom_components c on c.organization_id=i.organization_id and c.document_id=i.document_id where i.organization_id=p_organization_id and i.review_id=v_review.id
  ), decisions as (
    select c.identity_key,(array_agg(c.selected_source_component_id order by c.selected_source_component_id) filter(where c.conflict_type='incompatible_version' and c.selected_source_component_id is not null))[1] vc,(array_agg(c.selected_source_component_id order by c.selected_source_component_id) filter(where c.conflict_type='field_conflict' and c.selected_source_component_id is not null))[1] fc,bool_or(c.selected_source_component_id is null and c.resolution_reason is not null) excluded,bool_or(c.selected_source_component_id is null and c.resolution_reason is null) unresolved,count(*) conflict_count from public.sbom_composite_conflicts c where c.organization_id=p_organization_id and c.review_id=v_review.id group by c.identity_key
  ), selected as (
    select c.*,case when c.identity_key like 'unresolved:%' then 'component:'||c.document_id::text||':'||c.document_local_ref else 'component:'||encode(extensions.digest(c.identity_key||'@'||coalesce(c.normalized_version,''),'sha256'),'hex') end composite_ref from candidates c left join decisions d on d.identity_key=c.identity_key where not coalesce(d.excluded,false) and not coalesce(d.unresolved,false) and ((d.vc is not null and c.component_id=d.vc) or (d.vc is null and d.fc is not null and c.component_id=d.fc) or (d.conflict_count is null and c.rn=1) or c.identity_key like 'unresolved:%')
  )
  select coalesce(jsonb_agg(jsonb_build_object('componentRef',s.composite_ref,'name',coalesce((select c.normalized_name from public.sbom_composite_conflicts x join candidates c on c.component_id=x.selected_source_component_id where x.organization_id=p_organization_id and x.review_id=v_review.id and x.identity_key=s.identity_key and x.conflict_type='field_conflict' and x.field_name='name' and x.selected_source_component_id is not null order by x.id limit 1),s.normalized_name),'version',s.normalized_version,'canonicalPurl',coalesce((select c.canonical_purl from public.sbom_composite_conflicts x join candidates c on c.component_id=x.selected_source_component_id where x.organization_id=p_organization_id and x.review_id=v_review.id and x.identity_key=s.identity_key and x.conflict_type='field_conflict' and x.field_name='canonicalPurl' and x.selected_source_component_id is not null order by x.id limit 1),s.canonical_purl),'hashes',coalesce((select c.hashes from public.sbom_composite_conflicts x join candidates c on c.component_id=x.selected_source_component_id where x.organization_id=p_organization_id and x.review_id=v_review.id and x.identity_key=s.identity_key and x.conflict_type='field_conflict' and x.field_name='hashes' and x.selected_source_component_id is not null order by x.id limit 1),s.hashes),'sourceComponentId',s.component_id,'sourceId',s.source_id,'documentId',s.document_id) order by s.composite_ref,s.source_id,s.source_offset,s.component_id),'[]'::jsonb) into v_components from selected s;
  select coalesce(jsonb_agg(jsonb_build_object('fromRef',d.composite_parent_ref,'toRef',d.composite_child_ref) order by d.composite_parent_ref,d.composite_child_ref),'[]'::jsonb) into v_dependencies from (select distinct composite_parent_ref,composite_child_ref from public.sbom_composite_dependency_provenance d where d.organization_id=p_organization_id and d.review_id=v_review.id) d;
  return query select 'claimed'::text,jsonb_build_object('reviewId',v_review.id,'actorId',v_review.created_by,'productId',v_review.product_id,'releaseId',v_review.release_id,'mergeRulesVersion',v_review.merge_rules_version,'generatedSourceId',v_review.generated_source_id,'components',v_components,'dependencies',v_dependencies);
end;
$$;

create or replace function public.sbom_composite_review_json(p_organization_id uuid,p_review_id uuid)
returns jsonb language sql stable set search_path=public,pg_temp as $$
  select jsonb_build_object('id',r.id,'organizationId',r.organization_id,'productId',r.product_id,'releaseId',r.release_id,'state',r.status,'mergeRulesVersion',r.merge_rules_version,'inputSetDigest',r.input_set_digest,'resolutionDigest',r.resolution_digest,'coverage',jsonb_build_object('sourceCount',(select count(*) from public.sbom_composite_review_inputs i where i.organization_id=r.organization_id and i.review_id=r.id),'componentCandidateCount',(select count(distinct p.source_component_id) from public.sbom_composite_component_provenance p where p.organization_id=r.organization_id and p.review_id=r.id),'duplicateIdentityCount',0,'conflictCount',(select count(*) from public.sbom_composite_conflicts c where c.organization_id=r.organization_id and c.review_id=r.id),'unresolvedRelationshipCount',(select count(*) from public.sbom_composite_unresolved_relationships u where u.organization_id=r.organization_id and u.review_id=r.id and u.disposition is null)),'sources',coalesce((select jsonb_agg(jsonb_build_object('sourceId',i.source_id,'documentId',i.document_id,'documentSha256',i.source_sha256,'releaseId',i.release_id,'source',s.source_kind,'supplierSubmissionId',i.supplier_submission_id,'acceptedForComposite',i.supplier_submission_id is null or ss.status='accepted','retentionWarning',case when p.retention_protection_until is null then null else 'Retention protection applies to this input.' end) order by i.source_id) from public.sbom_composite_review_inputs i join public.sbom_sources s on s.organization_id=i.organization_id and s.id=i.source_id left join public.sbom_supplier_submissions ss on ss.organization_id=i.organization_id and ss.id=i.supplier_submission_id left join public.products p on p.organization_id=s.organization_id and p.id=s.product_id where i.organization_id=r.organization_id and i.review_id=r.id),'[]'::jsonb),'conflicts',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'reviewId',c.review_id,'identity',nullif(c.identity_key,''),'kind',c.conflict_type,'field',c.field_name,'state',case when c.resolved_at is null then 'unresolved' when c.selected_source_component_id is null then 'excluded' else 'resolved' end,'candidates',c.candidates,'selectedComponentId',c.selected_source_component_id,'resolutionReason',c.resolution_reason,'resolvedAt',c.resolved_at) order by c.created_at,c.id) from public.sbom_composite_conflicts c where c.organization_id=r.organization_id and c.review_id=r.id),'[]'::jsonb),'relationships',coalesce((select jsonb_agg(jsonb_build_object('id',u.id,'reviewId',u.review_id,'kind',coalesce(u.detail->>'kind','unresolved_endpoint'),'state',case u.disposition when 'include' then 'included' when 'omit' then 'excluded' else 'unresolved' end,'parentComponentId',u.detail->>'parentComponentId','childComponentId',u.detail->>'childComponentId','sourceId',u.detail->>'sourceId','documentId',u.detail->>'documentId','sourceParentRef',u.detail->>'sourceParentRef','sourceChildRef',u.detail->>'sourceChildRef','reason',u.resolution_reason,'resolvedAt',u.resolved_at) order by u.created_at,u.id) from public.sbom_composite_unresolved_relationships u where u.organization_id=r.organization_id and u.review_id=r.id),'[]'::jsonb),'retentionWarnings',coalesce((select jsonb_agg(w.warning order by w.warning) from (select distinct case when f.reason_kind='legal_hold' then 'At least one input is subject to an active legal hold.' else 'Input source retention requirements differ.' end warning from public.sbom_composite_review_inputs i join public.sbom_sources s on s.organization_id=i.organization_id and s.id=i.source_id join public.retention_authoritative_facts f on f.organization_id=s.organization_id and f.source_record_id=s.product_id and f.active where i.organization_id=r.organization_id and i.review_id=r.id union all select 'Input source retention protection periods differ.' where (select count(distinct coalesce(p.retention_protection_until,'-infinity'::timestamptz)) from public.sbom_composite_review_inputs i join public.sbom_sources s on s.organization_id=i.organization_id and s.id=i.source_id join public.products p on p.organization_id=s.organization_id and p.id=s.product_id where i.organization_id=r.organization_id and i.review_id=r.id)>1) w),'[]'::jsonb),'generatedSourceId',r.generated_source_id,'generatedDocumentId',r.generated_document_id,'provenanceManifest',case when r.status='completed' then jsonb_build_object('reviewId',r.id,'sourceHashes',(select jsonb_agg(i.source_sha256 order by i.source_sha256) from public.sbom_composite_review_inputs i where i.organization_id=r.organization_id and i.review_id=r.id),'mergeRulesVersion',r.merge_rules_version,'generatedAt',r.completed_at,'components',coalesce((select jsonb_agg(jsonb_build_object('compositeComponentRef',p.composite_component_ref,'field',p.field_name,'sourceId',p.source_id,'documentId',p.source_document_id,'documentSha256',i.source_sha256,'sourceComponentId',p.source_component_id,'sourceComponentRef',p.source_component_ref,'supplierSubmissionId',p.supplier_submission_id,'mergedAt',p.merge_timestamp,'reviewDecisionId',p.review_conflict_id) order by p.composite_component_ref,p.field_name,p.source_component_id) from public.sbom_composite_component_provenance p join public.sbom_composite_review_inputs i on i.organization_id=p.organization_id and i.review_id=p.review_id and i.source_id=p.source_id where p.organization_id=r.organization_id and p.review_id=r.id),'[]'::jsonb),'dependencies',coalesce((select jsonb_agg(jsonb_build_object('compositeFromRef',d.composite_parent_ref,'compositeToRef',d.composite_child_ref,'sourceId',d.source_id,'documentId',d.source_document_id,'documentSha256',i.source_sha256,'sourceFromComponentRef',parent.document_local_ref,'sourceToComponentRef',child.document_local_ref,'supplierSubmissionId',d.supplier_submission_id,'mergedAt',d.merge_timestamp,'reviewDecisionId',d.review_relationship_id) order by d.composite_parent_ref,d.composite_child_ref,d.source_dependency_id) from public.sbom_composite_dependency_provenance d join public.sbom_composite_review_inputs i on i.organization_id=d.organization_id and i.review_id=d.review_id and i.source_id=d.source_id and i.document_id=d.source_document_id join public.sbom_component_dependencies edge on edge.organization_id=d.organization_id and edge.id=d.source_dependency_id join public.sbom_components parent on parent.organization_id=edge.organization_id and parent.id=edge.parent_component_id join public.sbom_components child on child.organization_id=edge.organization_id and child.id=edge.child_component_id where d.organization_id=r.organization_id and d.review_id=r.id),'[]'::jsonb)) else null end,'error',r.failure_message,'createdAt',r.created_at,'updatedAt',r.updated_at,'completedAt',r.completed_at) from public.sbom_composite_reviews r where r.organization_id=p_organization_id and r.id=p_review_id;
$$;

revoke all on function public.normalize_sbom_composite_conflict_candidates(),public.sync_sbom_composite_selected_provenance(uuid,uuid),public.claim_sbom_composite_generation(uuid,uuid,integer),public.sbom_composite_review_json(uuid,uuid) from public,anon,authenticated;
grant execute on function public.normalize_sbom_composite_conflict_candidates(),public.sync_sbom_composite_selected_provenance(uuid,uuid),public.claim_sbom_composite_generation(uuid,uuid,integer),public.sbom_composite_review_json(uuid,uuid) to service_role;
